def dispatch(tools, tool_call):
    # tools: [{"name": str, "fn": callable}, ...]
    table = {t["name"]: t["fn"] for t in tools}
    name = tool_call["name"]
    args = tool_call.get("args", {})
    if name not in table:
        return {"error": f"unknown tool: {name}"}
    try:
        return {"result": table[name](**args)}
    except Exception as e:
        return {"error": str(e)}
要点：按 name 查表、用 **args 解包、对未知工具与异常做兜底。
